class ListNode:
    def __init__(self,x):
        self.val=x
        self.next=None

def detect(head):
    fast=head
    slow=head
    while fast and fast.next:
        slow=slow.next
        fast=fast.next.next
        if slow==fast:
            return True
    else:
        return False

n=int(input())
node={}
info=[]
if n==0:
    print("false")
else:
    for _ in range(n):
        addr,val,next_addr=map(int,input().split())
        node[addr]=ListNode(val)
        info.append((addr,next_addr))

    for addr,next_addr in info:
        if next_addr!=-1:
            node[addr].next=node[next_addr]
    head=node[info[0][0]]
    if detect(head):
        print("true")
    else:
        print("false")

n,target=map(int,input().split())
nums=list(map(int,input().split()))
left=0
right=n-1
while left<=right:
    mid=(right+left)//2
    if nums[mid]<target:
        left=mid+1
    else:
        right=mid-1
if left<n and nums[left]==target:
    print(left)
else:
    print(-1)
